; src/graphics/gfx.s — display bootstrap THROUGH THE graphics.library ABI (M4c2 engine, extended to the boot screen).
; gfx_display_init allocates the chip bitplanes, UNPACKS the boot image INTO them (kitten "KickSlopStart", 352x272x4 =
; 16 colours, ByteRun1 in the ROM), sets up the BitMap/RasInfo/ColorMap(16)/ViewPort/View structures, opens
; graphics.library (FindName), then calls MakeVPort/MrgCop/LoadView THROUGH THE JUMP TABLE -> the copper list (4 plane
; pointers + 16 colours) is GENERATED by the ABI. The image/palette data are generated by src/graphics/mk_bootscreen.py.
; History: M4a (Copper background) / M4b/M4c2 (striped bitplane) -> the striped screen is replaced here by the boot
; image; the same ABI path (generic MakeVPort, N planes/M colours) is therefore exercised more widely.
;
; CONSTRAINT: Copper and bitplane DMA (Agnus) read ONLY chip RAM -> bitplanes, structures and generated copper
; lists are all AllocMem(MEMF_CHIP); the image is unpacked ROM -> chip.
; IMPLEMENTATION track ("clean"): graphics.library AutoDocs + HRM + image supplied by the user. NO ROM reading.

                include "exec.i"
                include "graphics.i"

                xdef    gfx_display_init
                xdef    gfx_display_free
                xref    bootscreen_planes    ; bootscreen_data.s (generated): 4 planar bitplanes, ByteRun1
                xref    bootscreen_palette   ; bootscreen_data.s (generated): 16 OCS RGB444 colours
                xref    topaz8_font          ; text.s: the hand-authored topaz 8
                xref    kss_idstr            ; exec/boot.s: "KickSlopStart <version>" written by mkrom.py --id

; gfx_display_init(a6 = SysBase): allocates bitplanes + structure block, unpacks the image, sets up View/ViewPort/
; BitMap/ColorMap, FindName("graphics.library"), then MakeVPort/MrgCop/LoadView through the GfxBase jump table.
; RESTORES a6 = SysBase on exit (the scheduler handoff depends on it). Scratch d0/d1/a0/a1; d2/a2/a4/a5 saved.
; -> d0 = structure block (for gfx_display_free), 0 if an alloc or FindName failed (no display, boot continues).
gfx_display_init:
        movem.l d2/a2/a4/a5,-(sp)
        ; 1. chip bitplanes (4 contiguous planes), the image unpacked into them from the ROM. ByteRun1 (IFF): control
        ;    byte n = 0..127 -> n+1 literal bytes; -1..-127 -> the next byte -n+1 times; -128 -> nothing. Bounded by
        ;    the size of the planes whatever the stream says.
        move.l  #GFX_BOOT_PLANES_SZ,d0
        move.l  #(MEMF_CHIP|MEMF_CLEAR),d1
        jsr     LVO_ALLOCMEM(a6)
        tst.l   d0
        beq     .gfx_ret
        move.l  d0,a4                        ; a4 = bitplane base (chip)
        move.l  #bootscreen_planes,a0        ; src = ByteRun1 stream (ROM)
        move.l  a4,a1                         ; dst = chip
        move.l  #GFX_BOOT_PLANES_SZ,d1       ; d1 = bytes still to write
.gfx_unp:
        tst.l   d1
        beq.s   .gfx_unpd
        moveq   #0,d0
        move.b  (a0)+,d0
        bmi.s   .gfx_run
        addq.w  #1,d0                        ; literals: n+1 bytes
        cmp.l   d1,d0
        bls.s   .gfx_lit
        move.l  d1,d0
.gfx_lit:
        sub.l   d0,d1
        subq.w  #1,d0
.gfx_lcp:
        move.b  (a0)+,(a1)+
        dbf     d0,.gfx_lcp
        bra.s   .gfx_unp
.gfx_run:
        cmp.b   #$80,d0
        beq.s   .gfx_unp                     ; -128: nothing
        neg.b   d0
        addq.w  #1,d0                        ; run: -n+1 copies of the next byte
        cmp.l   d1,d0
        bls.s   .gfx_rn
        move.l  d1,d0
.gfx_rn:
        sub.l   d0,d1
        subq.w  #1,d0
        move.b  (a0)+,d2
.gfx_rcp:
        move.b  d2,(a1)+
        dbf     d0,.gfx_rcp
        bra.s   .gfx_unp
.gfx_unpd:
        ; 2. chip structure block (View/VP/RasInfo/BitMap/ColorMap/ColorTable[32])
        move.l  #GFX_STRUCT_SIZE,d0
        move.l  #(MEMF_CHIP|MEMF_CLEAR),d1
        jsr     LVO_ALLOCMEM(a6)
        tst.l   d0
        beq     .gfx_noview
        move.l  d0,a2                        ; a2 = structure block
        ; BitMap (overscan 352x272)
        move.w  #GFX_BOOT_BYTES,GFX_O_BITMAP+bm_BytesPerRow(a2)
        move.w  #GFX_BOOT_H,GFX_O_BITMAP+bm_Rows(a2)
                ifeq    BOOTSCR_ONE_PLANE
        move.b  #GFX_BOOT_DEPTH,GFX_O_BITMAP+bm_Depth(a2)
                else
        move.b  #1,GFX_O_BITMAP+bm_Depth(a2) ; RED BOOTSCR_ONE_PLANE: 1 plane -> image destroyed (2 colours)
                endc
        ; Planes[0..GFX_BOOT_DEPTH-1] = base + i*GFX_BPL_SIZE (contiguous planes)
        lea     GFX_O_BITMAP+bm_Planes(a2),a0
        move.l  a4,d0
        moveq   #GFX_BOOT_DEPTH-1,d1
.gfx_pl:
        move.l  d0,(a0)+
        add.l   #GFX_BOOT_PLANE_SZ,d0
        dbf     d1,.gfx_pl
        ; RasInfo -> BitMap
        lea     GFX_O_BITMAP(a2),a0
        move.l  a0,GFX_O_RASINFO+ri_BitMap(a2)
        ; ColorMap: 16 colours copied from the ROM palette
        move.w  #GFX_BOOT_NCOLORS,GFX_O_COLORMAP+cm_Count(a2)
        lea     GFX_O_COLORTAB(a2),a0
        move.l  a0,GFX_O_COLORMAP+cm_ColorTable(a2)
        move.l  #bootscreen_palette,a1
        move.w  #GFX_BOOT_NCOLORS-1,d0
.gfx_pal:
        move.w  (a1)+,(a0)+
        dbf     d0,.gfx_pal
        ; ViewPort (overscan 352x272)
        move.w  #GFX_BOOT_W,GFX_O_VP+vp_DWidth(a2)
        move.w  #GFX_BOOT_H,GFX_O_VP+vp_DHeight(a2)
        move.w  #GFX_BOOT_DX,GFX_O_VP+vp_DxOffset(a2)
        move.w  #GFX_BOOT_DY,GFX_O_VP+vp_DyOffset(a2)
        lea     GFX_O_RASINFO(a2),a0
        move.l  a0,GFX_O_VP+vp_RasInfo(a2)
        lea     GFX_O_COLORMAP(a2),a0
        move.l  a0,GFX_O_VP+vp_ColorMap(a2)
        ; View -> ViewPort
        lea     GFX_O_VP(a2),a0
        move.l  a0,GFX_O_VIEW+v_ViewPort(a2)
        move.w  #$2C,GFX_O_VIEW+v_DyOffset(a2) ; InitView's offsets: MrgCop places the ViewPort from them
        move.w  #$81,GFX_O_VIEW+v_DxOffset(a2)
        ; 3. FindName("graphics.library")
        lea     EB_LIBLIST(a6),a0
        lea     gfx_libname(pc),a1
        jsr     LVO_FINDNAME(a6)
        tst.l   d0
        beq     .gfx_nogfx                   ; no graphics.library -> no display
        move.l  d0,a5                        ; a5 = GfxBase
        btst    #0,gb_DisplayFlags+1(a5)     ; DISPF_NTSC: 272 lines do not fit under MaxDisplayRow
        beq.s   .gfx_rows
        move.w  #GFX_BOOT_NTSC_H,GFX_O_VP+vp_DHeight(a2)
        move.w  #(GFX_BOOT_H-GFX_BOOT_NTSC_H)/2,GFX_O_RASINFO+ri_RyOffset(a2)
.gfx_rows:
        move.l  a5,a6
        bsr     gfx_boottext
        ; 4. MakeVPort(view,vp); MrgCop(view); LoadView(view) THROUGH THE JUMP TABLE
        lea     GFX_O_VIEW(a2),a0
        lea     GFX_O_VP(a2),a1
        move.l  a5,a6
        jsr     LVO_MAKEVPORT(a6)
        move.l  a5,a6
        lea     GFX_O_VIEW(a2),a1
        jsr     LVO_MRGCOP(a6)
        move.l  a5,a6
        lea     GFX_O_VIEW(a2),a1
        jsr     LVO_LOADVIEW(a6)
        move.l  a2,d0
.gfx_ret:
        move.l  ($4).w,a6                    ; restore a6 = SysBase (scheduler handoff)
        movem.l (sp)+,d2/a2/a4/a5
        rts
.gfx_nogfx:
        move.l  a2,a1
        move.l  #GFX_STRUCT_SIZE,d0
        jsr     LVO_FREEMEM(a6)
.gfx_noview:
        move.l  a4,a1
        move.l  #GFX_BOOT_PLANES_SZ,d0
        jsr     LVO_FREEMEM(a6)
        moveq   #0,d0
        bra.s   .gfx_ret

; gfx_display_free(a0 = structure block from gfx_display_init, a6 = SysBase): takes the boot screen down when a
; floppy inserted on it boots: LoadView(NULL) first (the copper must leave the lists), then its copper lists, planes
; and structures go back to the free list: a game booted from there finds the chip RAM of a power-on boot.
; Preserves d2-d7/a2-a6.
gfx_display_free:
        movem.l a2/a5/a6,-(sp)
        move.l  a0,a2
        lea     EB_LIBLIST(a6),a0
        lea     gfx_libname(pc),a1
        jsr     LVO_FINDNAME(a6)
        move.l  d0,a5                        ; gfx_display_init succeeded: graphics.library is there
        move.l  a5,a6
        suba.l  a1,a1
        jsr     LVO_LOADVIEW(a6)
        lea     GFX_O_VP(a2),a0
        jsr     LVO_FREEVPORTCOPLISTS(a6)
        move.l  GFX_O_VIEW+v_LOFCprList(a2),a0
        jsr     LVO_FREECPRLIST(a6)
        move.l  ($4).w,a6
        move.l  GFX_O_BITMAP+bm_Planes(a2),a1
        move.l  #GFX_BOOT_PLANES_SZ,d0
        jsr     LVO_FREEMEM(a6)
        move.l  a2,a1
        move.l  #GFX_STRUCT_SIZE,d0
        jsr     LVO_FREEMEM(a6)
        movem.l (sp)+,a2/a5/a6
        rts

; gfx_boottext(a2 = structure block, a6 = GfxBase): the text of the insert-disk screen, drawn in colour 1 (black) in the
; column right of the logo: the request, then "KickSlopStart" and the build number of the ROM ID block, cut into
; lines of GFX_TXT_COLS characters (a long local `git describe` takes two lines). Preserves d2-d7/a2-a6.
GFX_TXT_X       EQU 228                      ; first column (the logo ends at 216)
GFX_TXT_Y       EQU 112                      ; baseline of the first line
GFX_TXT_LINE    EQU 10                       ; line spacing
GFX_TXT_COLS    EQU (GFX_BOOT_W-GFX_TXT_X)/8 ; characters of 8 pixels left on a line
gfx_boottext:
        movem.l d2-d4/a2-a4,-(sp)
        lea     -rp_SIZEOF(sp),sp
        move.l  sp,a1
        jsr     LVO_INITRASTPORT(a6)
        lea     GFX_O_BITMAP(a2),a0
        move.l  a0,rp_BitMap(sp)
        move.l  sp,a1
        lea     topaz8_font,a0
        jsr     LVO_SETFONT(a6)
        move.l  sp,a1
        moveq   #1,d0
        jsr     LVO_SETAPEN(a6)
        move.l  sp,a1
        moveq   #JAM1,d0
        jsr     LVO_SETDRMD(a6)
        move.w  #GFX_TXT_Y,d4                ; d4 = baseline of the next line
        lea     gfx_txt_lines(pc),a3         ; fixed lines, an empty one leaves a gap, a double NUL ends them
.bt_fixed:
        tst.b   (a3)
        bne.s   .bt_line
        tst.b   1(a3)
        beq.s   .bt_id
        addq.l  #1,a3
        add.w   #GFX_TXT_LINE,d4
        bra.s   .bt_fixed
.bt_line:
        move.l  a3,a0
        bsr.s   .bt_put
        move.l  a0,a3
        addq.l  #1,a3                        ; past its NUL
        bra.s   .bt_fixed
.bt_id:
        lea     kss_idstr,a3                 ; the version, without the "KickSlopStart " already shown
        lea     gfx_txt_kss(pc),a0
        move.l  a3,a1
.bt_pre:
        tst.b   (a0)
        beq.s   .bt_sp
        cmpm.b  (a0)+,(a1)+
        beq.s   .bt_pre
        bra.s   .bt_ver                      ; another string: shown whole
.bt_sp:
        cmp.b   #' ',(a1)+
        bne.s   .bt_ver
        move.l  a1,a3
.bt_ver:
        tst.b   (a3)
        beq.s   .bt_ret
        move.l  a3,a0
        bsr.s   .bt_put
        move.l  a0,a3
        bra.s   .bt_ver
.bt_ret:
        lea     rp_SIZEOF(sp),sp
        movem.l (sp)+,d2-d4/a2-a4
        rts
.bt_put:                                     ; a0 = text: at most GFX_TXT_COLS characters of it on the line d4, then
        move.l  a0,a4                        ; the next line; -> a0 = first character not shown
        moveq   #0,d2
.bp_len:
        tst.b   (a4)
        beq.s   .bp_go
        cmp.w   #GFX_TXT_COLS,d2
        beq.s   .bp_go
        addq.l  #1,a4
        addq.w  #1,d2
        bra.s   .bp_len
.bp_go:
        move.l  a0,d3
        lea     4(sp),a1                     ; the RastPort (under the return address)
        move.w  #GFX_TXT_X,d0
        move.w  d4,d1
        jsr     LVO_MOVE(a6)
        lea     4(sp),a1
        move.l  d3,a0
        move.w  d2,d0
        jsr     LVO_TEXT(a6)
        add.w   #GFX_TXT_LINE,d4
        move.l  a4,a0
        rts

gfx_txt_lines:                               ; each line ends with its NUL; one more NUL: an empty line; two: the end
        dc.b    "Insert disk",0,"in DF0:",0,0
gfx_txt_kss:                                 ; also the prefix taken off the ID string
        dc.b    "KickSlopStart",0,0,0
gfx_libname:
        dc.b    "graphics.library",0
        EVEN
